-- =====================================================================
-- Migration 102: تعديل قانون الضريبة على الدخل 91/2005 بموجب
--                        القانون رقم 199 لسنة 2020
-- =====================================================================
--
-- سابع عشر (والأخير فى سلسلة تعديلات قانون 91/2005 نفسه المخطَّطة) -
--   بعد 084: 181/2005، 085: 1/2007، 086: 101/2012، 087: 11/2013، 088:
--   164/2013، 090: 53/2014، 091: 201/2014، 092: 17/2015، 093: 96/2015،
--   095: 82/2017، 096: 76/2017، 097: 29/2018، 098: 97/2018، 099:
--   158/2018، 100: 10/2019، 101: 26/2020.
--
-- المصدر: الجريدة الرسمية، العدد 39 مكرر (ز)، 30 سبتمبر 2020، سبع
--   صفحات (5-11). قُرئ بصريًا بالكامل (2.5x نظرة عامة ثم 6x-18x لكل
--   عبارة حرجة)، دون الاعتماد على الطبقة النصية المُستخرَجة مباشرة.
--   موقَّع الرئيس عبد الفتاح السيسى 2020-09-29؛ صدر العدد 2020-09-30.
--
-- ⚠️ هذا القانون يُعدِّل قانونين معًا: ضريبة الدمغة 111/1980 (المادة
--   الأولى - خارج النطاق تمامًا، غير مبنية هنا) وقانون 91/2005 (المواد
--   الثانية والثالثة - النطاق الوحيد المُنفَّذ أدناه).
--
-- ست عمليات (المادتان الثانية والثالثة من هذا القانون):
--   1) المادة (46 مكررًا 1/الفقرة الأولى) - استبدال جزئى (فقرة أولى
--      فقط، الفقرة الثانية بلا تغيير).
--   2) المادة (46 مكررًا 2) - استبدال كامل: تغيير جوهرى فى شرط تخفيض
--      السعر (من نسبة مساهمة+مدة حيازة إلى قيد بالبورصة المصرية).
--   3) المادة (46 مكررًا 5) - استبدال كامل (فقرتان → ثلاث فقرات).
--      ⚠️ غياب مؤكَّد بصريًا لكلمة "المصرية" بعد "بورصة الأوراق
--      المالية" فى الفقرة الأولى، خلافًا للنص السابق.
--   4) المادة (56 مكررًا) [article_no=56, suffix=2] - استبدال كامل.
--      ⚠️ تحديد الصف الصحيح بمطابقة المحتوى (توزيعات الأرباح، المُضافة
--      بالقانون 53/2014) تمييزًا عن suffix=1 (المُضافة بالقانون
--      101/2012، موضوع مختلف). تغيير جوهرى: نطاق فقرة الأرباح
--      الرأسمالية (46مكررا3) تحوَّل من "غير المقيمين" إلى "المقيمين".
--   5) المادة (46 مكررًا 3) - إضافة فقرتين (ثانية وثالثة): استثناء
--      غير المقيم من الضريبة على أوراق مالية مقيدة بالبورصة المصرية
--      وعلى أذون الخزانة.
--   6) المادة (50) - إضافة بند جديد برقم (13)، بعد البند (10) مباشرة
--      (لا بند 11/12 فى قاعدة البيانات - مؤكَّد أنه ليس فجوة بناء، بل
--      ترقيم المُشرِّع نفسه).
--
-- effective_from = 2020-10-01 (اليوم التالى لتاريخ نشر الجريدة
--   2020-09-30، عملاً بالمادة التاسعة من هذا القانون).
--
-- المادة الأولى (ضريبة الدمغة) والمادة الثامنة (إلغاء كل حكم مخالف -
--   حكم عام قياسى) غير مُنفَّذتين. المواد الرابعة-السابعة (أحكام
--   انتقالية مستقلة: تأجيل/تجاوز ضريبى) موثَّقة فى
--   law_199_2020_amendments.py، غير مُنفَّذة كعمليات (قرار معمارى معتمد
--   2026-10-02: تُمثَّل مستقبلاً كسجلات تشريعية مستقلة غير مربوطة برقم
--   مادة دائم، لم يُصمَّم جدولها بعد).
--
-- نفس القرار المعمارى المُثبَّت فى migrations 084-101 (UPDATE مباشر -
--   استثناء مُحدَّد النطاق لقانون 91/2005 فقط).
--
-- قابلة لإعادة التشغيل بأمان (idempotent) - UPDATE بقيمة ثابتة.
--
-- هذه آخر هجرة فى سلسلة تعديلات قانون 91/2005 نفسه (17 قانون تعديل
--   مخطَّط، باستثناء فجوة القانون 73/2010 الموثَّقة والمؤجَّلة بقرار
--   صاحب المشروع 2026-10-02).
--
-- =====================================================================

BEGIN;

-- ===== عمليات التعديل =====
-- مادة 46 (suffix=2) - UPDATE (effective_from=2020-10-01)
UPDATE articles SET body = $b102_1$يتحدد وعاء الضريبة على توزيعات الأرباح المنصوص عليها فى المادة (46 مكررًا) بالنسبة لما يحصل عليه الشخص الطبيعى المقيم وفقًا لما تقرره السلطة المختصة بالتوزيع .
ويشمل ذلك الوعاء بالنسبة للشخص الطبيعى المقيم الذى يزاول نشاطًا خاضعًا للضريبة وفقًا لأحكام الباب الثالث من الكتاب الثانى من القانون كامل توزيعات الأرباح التى يحصل عليها ، سواء من مصدر فى مصر أو فى الخارج .$b102_1$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 2;

UPDATE article_versions SET
    body = $b102_1$يتحدد وعاء الضريبة على توزيعات الأرباح المنصوص عليها فى المادة (46 مكررًا) بالنسبة لما يحصل عليه الشخص الطبيعى المقيم وفقًا لما تقرره السلطة المختصة بالتوزيع .
ويشمل ذلك الوعاء بالنسبة للشخص الطبيعى المقيم الذى يزاول نشاطًا خاضعًا للضريبة وفقًا لأحكام الباب الثالث من الكتاب الثانى من القانون كامل توزيعات الأرباح التى يحصل عليها ، سواء من مصدر فى مصر أو فى الخارج .$b102_1$,
    effective_from = '2020-10-01'::date,
    amended_by_law_no = 199,
    amended_by_law_year = 2020,
    change_note = $n102_1$القانون 199/2020 (المادة الثانية): استبدال الفقرة الأولى فقط من المادة (46 مكررًا 1) - تغيير وعاء الضريبة على توزيعات الأرباح للشخص الطبيعى المقيم إلى وفق ما تقرره السلطة المختصة بالتوزيع دون النص على حد العشرة آلاف جنيه السابق. الفقرة الثانية (حكم من يزاول نشاطًا خاضعًا للضريبة) بلا تغيير.$n102_1$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 2
) AND version_no = 1;

-- مادة 46 (suffix=3) - UPDATE (effective_from=2020-10-01)
UPDATE articles SET body = $b102_2$استثناء من حكم المادة (8) من هذا القانون ، يكون سعر الضريبة على توزيعات الأرباح المنصوص عليها فى المادة (46 مكررًا) المحققة من مصدر فى مصر فى خلال السنة التى يحصل عليها شخص طبيعى مقيم (10%) وذلك دون خصم أى تكاليف ، ويخفض هذا السعر إلى (5%) إذا كانت الأوراق المالية مقيدة فى بورصة الأوراق المالية المصرية .
وعلى الجهات التى تنفذ هذه المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة فى موعد أقصاه خمسة أيام عمل من بداية الشهر التالى للشهر الذى تم فيه التحصيل ، وذلك على النموذج المعد لذلك .$b102_2$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 3;

UPDATE article_versions SET
    body = $b102_2$استثناء من حكم المادة (8) من هذا القانون ، يكون سعر الضريبة على توزيعات الأرباح المنصوص عليها فى المادة (46 مكررًا) المحققة من مصدر فى مصر فى خلال السنة التى يحصل عليها شخص طبيعى مقيم (10%) وذلك دون خصم أى تكاليف ، ويخفض هذا السعر إلى (5%) إذا كانت الأوراق المالية مقيدة فى بورصة الأوراق المالية المصرية .
وعلى الجهات التى تنفذ هذه المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة فى موعد أقصاه خمسة أيام عمل من بداية الشهر التالى للشهر الذى تم فيه التحصيل ، وذلك على النموذج المعد لذلك .$b102_2$,
    effective_from = '2020-10-01'::date,
    amended_by_law_no = 199,
    amended_by_law_year = 2020,
    change_note = $n102_2$القانون 199/2020 (المادة الثانية): استبدال كامل للمادة (46 مكررًا 2). تغيير جوهرى: شرط تخفيض السعر من 10% إلى 5% تحوَّل من (نسبة مساهمة تزيد على 25% + مدة حيازة سنتين على الأقل) إلى (قيد الأوراق المالية فى بورصة الأوراق المالية المصرية) فقط؛ وإلغاء آلية الحجز المسبق بنسبة 1% واستبدالها بحجز كامل الضريبة المستحقة خلال 5 أيام عمل من بداية الشهر التالى للتحصيل.$n102_2$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 3
) AND version_no = 1;

-- مادة 46 (suffix=6) - UPDATE (effective_from=2020-10-01)
UPDATE articles SET body = $b102_3$استثناء من حكم المادة (8) من هذا القانون ، تخضع للضريبة الأرباح الرأسمالية المنصوص عليها فى المادة (46 مكررًا 4) المحققة من الأوراق المالية المقيدة فى بورصة الأوراق المالية التى يحصل عليها الشخص الطبيعى المقيم من مصدر فى مصر بسعر (10%) وذلك دون خصم أى تكاليف .
وعلى الجهات التى تنفذ المعاملة إخطار الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة بالمعاملة ، وذلك على النموذج المعد لذلك فى موعد أقصاه نهاية شهر يناير من كل عام .
كما أن على الجهات المشار إليها فى الفقرة الثانية من هذه المادة إخطار المصلحة ببيان تفصيلى بإجمالى ناتج التصرف فى الأوراق المالية لكل ممول فى نهاية الفترة الضريبية ، وتحدد الأرباح الرأسمالية السنوية الخاضعة للضريبة على أساس قيمة صافى الأرباح الرأسمالية لمحفظة الأوراق المالية المحققة فى نهاية الفترة الضريبية على أساس الفرق بين سعر بيع أو استبدال أو أى صورة من صور التصرف فى الأوراق المالية أو الحصص وبين تكلفة اقتنائها بعد خصم عمولة الوساطة .$b102_3$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 6;

UPDATE article_versions SET
    body = $b102_3$استثناء من حكم المادة (8) من هذا القانون ، تخضع للضريبة الأرباح الرأسمالية المنصوص عليها فى المادة (46 مكررًا 4) المحققة من الأوراق المالية المقيدة فى بورصة الأوراق المالية التى يحصل عليها الشخص الطبيعى المقيم من مصدر فى مصر بسعر (10%) وذلك دون خصم أى تكاليف .
وعلى الجهات التى تنفذ المعاملة إخطار الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة بالمعاملة ، وذلك على النموذج المعد لذلك فى موعد أقصاه نهاية شهر يناير من كل عام .
كما أن على الجهات المشار إليها فى الفقرة الثانية من هذه المادة إخطار المصلحة ببيان تفصيلى بإجمالى ناتج التصرف فى الأوراق المالية لكل ممول فى نهاية الفترة الضريبية ، وتحدد الأرباح الرأسمالية السنوية الخاضعة للضريبة على أساس قيمة صافى الأرباح الرأسمالية لمحفظة الأوراق المالية المحققة فى نهاية الفترة الضريبية على أساس الفرق بين سعر بيع أو استبدال أو أى صورة من صور التصرف فى الأوراق المالية أو الحصص وبين تكلفة اقتنائها بعد خصم عمولة الوساطة .$b102_3$,
    effective_from = '2020-10-01'::date,
    amended_by_law_no = 199,
    amended_by_law_year = 2020,
    change_note = $n102_3$القانون 199/2020 (المادة الثانية): استبدال كامل للمادة (46 مكررًا 5)، من فقرتين إلى ثلاث فقرات. ⚠️ ملاحظة مصدرية مؤكَّدة بصريًا (تكبير 14x): الفقرة الأولى لا تتضمن كلمة 'المصرية' بعد 'بورصة الأوراق المالية' خلافًا للنص القديم - نُقلت كما وردت فى المصدر دون إضافة. الفقرة الثانية استبدلت موعد الإخطار (كان دون موعد محدد صراحة) بموعد أقصاه نهاية يناير من كل عام. الفقرة الثالثة جديدة كليًا (بيان تفصيلى سنوى وإعادة حساب الأرباح الرأسمالية السنوية).$n102_3$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 6
) AND version_no = 1;

-- مادة 56 (suffix=2) - UPDATE (effective_from=2020-10-01)
UPDATE articles SET body = $b102_4$تخضع للضريبة بسعر (10%) دون خصم أى تكاليف توزيعات الأرباح التى تجريها شركات الأموال أو شركات الأشخاص بما فى ذلك الشركات المقامة بنظام المناطق الاقتصادية ذات الطبيعة الخاصة للشخص الطبيعى غير المقيم والشخص الاعتبارى المقيم وغير المقيم بما فى ذلك أرباح الأشخاص الاعتبارية غير المقيمة التى تحققها من خلال منشأة دائمة فى مصر ، عدا التوزيعات التى تتم فى صور أسهم مجانية . ويكون سعر هذه الضريبة (5%) من توزيعات الأرباح إذا كانت الأوراق المالية مقيدة فى بورصة الأوراق المالية المصرية دون خصم أى تكاليف .
وتعد أرباح الأشخاص الاعتبارية غير المقيمة التى تحققها من خلال منشأة دائمة فى مصر موزعة حكمًا خلال ستين يومًا من تاريخ ختام السنة المالية للمنشأة الدائمة .
وتستبعد توزيعات الأرباح التى تحصل عليها الأشخاص الاعتبارية المقيمة من أشخاص اعتبارية مقيمة أخرى وما يقابلها من تكلفة من وعاء الضريبة على أرباح الأشخاص الاعتبارية المنصوص عليها فى الكتاب الثالث من هذا القانون وفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
وعلى الجهات التى تنفذ المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة فى موعد أقصاه خمسة أيام عمل من بداية الشهر التالى للشهر الذى تم فيه التحصيل ، وذلك على النموذج المعد لذلك .
وتخضع الأرباح الرأسمالية المنصوص عليها فى المادة (46 مكررًا 3) من هذا القانون التى يحصل عليها المقيمون من الأشخاص الطبيعيين والاعتباريين للضريبة ، ويكون سعر الضريبة (10%) على الأرباح الرأسمالية الناتجة عن التعامل فى الأوراق المالية المقيدة فى بورصة الأوراق المالية دون خصم أى تكاليف .
وتحدد الأرباح الرأسمالية الخاضعة للضريبة على أساس قيمة صافى الأرباح الرأسمالية لمحفظة الأوراق المالية المحققة فى نهاية الفترة الضريبية على أساس الفرق بين سعر بيع أو استبدال أو أية صورة من صور التصرف فى الأوراق المالية أو الحصص وبين تكلفة اقتنائها بعد خصم عمولة الوساطة .
كما أن على الجهات المشار إليها فى الفقرة الرابعة من هذه المادة إخطار المصلحة ببيان تفصيلى بإجمالى ناتج التصرف فى الأوراق المالية لكل ممول عن فترته الضريبية ، وذلك على النموذج المعد لذلك خلال خمسة أيام عمل من انتهاء هذه الفترة .
فإذا أسفر البيان المشار إليه عن أن الممول قد حقق أرباحًا رأسمالية صافية ، يُعاد حساب الضريبة على أساس إجمالى الأرباح الرأسمالية الصافية .
وعلى المصلحة مطالبة الممول بالضريبة المستحقة على الوعاء السنوى الناتج عن جميع تعاملاته بالأوراق المالية على النموذج الذى تحدده اللائحة التنفيذية لهذا القانون ، ويجب على المصلحة فى حالة امتناع الممول عن أداء الضريبة المستحقة على الأرباح المحققة من التعامل فى الأوراق المالية المقيدة بالبورصة إخطار كل من الهيئة العامة للرقابة المالية ، والجهة التى نفذت التعاملات بذلك .$b102_4$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 56 AND article_suffix_order = 2;

UPDATE article_versions SET
    body = $b102_4$تخضع للضريبة بسعر (10%) دون خصم أى تكاليف توزيعات الأرباح التى تجريها شركات الأموال أو شركات الأشخاص بما فى ذلك الشركات المقامة بنظام المناطق الاقتصادية ذات الطبيعة الخاصة للشخص الطبيعى غير المقيم والشخص الاعتبارى المقيم وغير المقيم بما فى ذلك أرباح الأشخاص الاعتبارية غير المقيمة التى تحققها من خلال منشأة دائمة فى مصر ، عدا التوزيعات التى تتم فى صور أسهم مجانية . ويكون سعر هذه الضريبة (5%) من توزيعات الأرباح إذا كانت الأوراق المالية مقيدة فى بورصة الأوراق المالية المصرية دون خصم أى تكاليف .
وتعد أرباح الأشخاص الاعتبارية غير المقيمة التى تحققها من خلال منشأة دائمة فى مصر موزعة حكمًا خلال ستين يومًا من تاريخ ختام السنة المالية للمنشأة الدائمة .
وتستبعد توزيعات الأرباح التى تحصل عليها الأشخاص الاعتبارية المقيمة من أشخاص اعتبارية مقيمة أخرى وما يقابلها من تكلفة من وعاء الضريبة على أرباح الأشخاص الاعتبارية المنصوص عليها فى الكتاب الثالث من هذا القانون وفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
وعلى الجهات التى تنفذ المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة فى موعد أقصاه خمسة أيام عمل من بداية الشهر التالى للشهر الذى تم فيه التحصيل ، وذلك على النموذج المعد لذلك .
وتخضع الأرباح الرأسمالية المنصوص عليها فى المادة (46 مكررًا 3) من هذا القانون التى يحصل عليها المقيمون من الأشخاص الطبيعيين والاعتباريين للضريبة ، ويكون سعر الضريبة (10%) على الأرباح الرأسمالية الناتجة عن التعامل فى الأوراق المالية المقيدة فى بورصة الأوراق المالية دون خصم أى تكاليف .
وتحدد الأرباح الرأسمالية الخاضعة للضريبة على أساس قيمة صافى الأرباح الرأسمالية لمحفظة الأوراق المالية المحققة فى نهاية الفترة الضريبية على أساس الفرق بين سعر بيع أو استبدال أو أية صورة من صور التصرف فى الأوراق المالية أو الحصص وبين تكلفة اقتنائها بعد خصم عمولة الوساطة .
كما أن على الجهات المشار إليها فى الفقرة الرابعة من هذه المادة إخطار المصلحة ببيان تفصيلى بإجمالى ناتج التصرف فى الأوراق المالية لكل ممول عن فترته الضريبية ، وذلك على النموذج المعد لذلك خلال خمسة أيام عمل من انتهاء هذه الفترة .
فإذا أسفر البيان المشار إليه عن أن الممول قد حقق أرباحًا رأسمالية صافية ، يُعاد حساب الضريبة على أساس إجمالى الأرباح الرأسمالية الصافية .
وعلى المصلحة مطالبة الممول بالضريبة المستحقة على الوعاء السنوى الناتج عن جميع تعاملاته بالأوراق المالية على النموذج الذى تحدده اللائحة التنفيذية لهذا القانون ، ويجب على المصلحة فى حالة امتناع الممول عن أداء الضريبة المستحقة على الأرباح المحققة من التعامل فى الأوراق المالية المقيدة بالبورصة إخطار كل من الهيئة العامة للرقابة المالية ، والجهة التى نفذت التعاملات بذلك .$b102_4$,
    effective_from = '2020-10-01'::date,
    amended_by_law_no = 199,
    amended_by_law_year = 2020,
    change_note = $n102_4$القانون 199/2020 (المادة الثانية): استبدال كامل للمادة (56 مكررًا). القانون يشير إليها دون رقم فرعى؛ حُدِّد الصف المقصود (article_no=56, suffix=2، المُضافة بالقانون 53/2014) بمطابقة المحتوى (توزيعات أرباح شركات الأموال/الأشخاص) تمييزًا عن (article_no=56, suffix=1، المُضافة بالقانون 101/2012، وموضوعها مختلف تمامًا: ضريبة الطرح لأول مرة والاستحواذ). ⚠️ تغيير جوهرى مؤكَّد بصريًا (تكبير 10x): نطاق فقرة الأرباح الرأسمالية المحالة للمادة (46 مكررًا 3) تحوَّل من 'غير المقيمين' فى النص القديم إلى 'المقيمين' فى النص الجديد.$n102_4$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 56 AND a.article_suffix_order = 2
) AND version_no = 1;

-- مادة 46 (suffix=4) - UPDATE (effective_from=2020-10-01)
UPDATE articles SET body = $b102_5$تسرى الضريبة على الأرباح الرأسمالية التى تتحقق من التصرف فى الأوراق المالية أو الحصص بالشركات ، سواء تحققت هذه الأرباح بالشركات أو فى الخارج .
ولا تسرى الضريبة المنصوص عليها فى الفقرة الأولى من هذه المادة على الأرباح الرأسمالية التى يحققها غير المقيم من الأشخاص الطبيعيين أو الاعتباريين من التصرف فى الأوراق المالية المقيدة ببورصة الأوراق المالية المصرية .
كما لا تسرى هذه الضريبة على الأرباح الرأسمالية التى يحققها غير المقيم من التصرف فى أذون الخزانة .$b102_5$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 4;

UPDATE article_versions SET
    body = $b102_5$تسرى الضريبة على الأرباح الرأسمالية التى تتحقق من التصرف فى الأوراق المالية أو الحصص بالشركات ، سواء تحققت هذه الأرباح بالشركات أو فى الخارج .
ولا تسرى الضريبة المنصوص عليها فى الفقرة الأولى من هذه المادة على الأرباح الرأسمالية التى يحققها غير المقيم من الأشخاص الطبيعيين أو الاعتباريين من التصرف فى الأوراق المالية المقيدة ببورصة الأوراق المالية المصرية .
كما لا تسرى هذه الضريبة على الأرباح الرأسمالية التى يحققها غير المقيم من التصرف فى أذون الخزانة .$b102_5$,
    effective_from = '2020-10-01'::date,
    amended_by_law_no = 199,
    amended_by_law_year = 2020,
    change_note = $n102_5$القانون 199/2020 (المادة الثالثة): إضافة فقرتين جديدتين (ثانية وثالثة) إلى المادة (46 مكررًا 3) - استثناء غير المقيم (أشخاص طبيعيين واعتباريين) من سريان الضريبة على الأرباح الرأسمالية الناتجة عن التصرف فى أوراق مالية مقيدة بالبورصة المصرية (فقرة ثانية) أو فى أذون الخزانة (فقرة ثالثة). الفقرة الأولى (الأصلية) بلا تغيير.$n102_5$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 4
) AND version_no = 1;

-- مادة 50 (suffix=0) - UPDATE (effective_from=2020-10-01)
UPDATE articles SET body = $b102_6$يعفى من الضريبة :
1 - الوزارات والمصالح الحكومية .
2 - المنشآت التعليمية الخاضعة لإشراف الدولة التى لا تستهدف أساسًا الحصول على الربح .
3 - الجمعيات والمؤسسات الأهلية المنشأة طبقًا لأحكام قانون الجمعيات والمؤسسات الأهلية الصادر بالقانون رقم 84 لسنة 2002 وذلك فى حدود الغرض الذى تأسست من أجله .
4 - الجهات التى لا تهدف إلى الربح وتباشر أنشطة ذات طبيعة اجتماعية أو علمية أو رياضية أو ثقافية وذلك فى حدود ما تقوم به من نشاط ليست له صفة تجارية أو صناعية أو مهنية .
5 - أرباح صناديق التأمين الخاصة الخاضعة لأحكام القانون 54 لسنة 1975 .
6 - المنظمات الدولية وهيئات التعاون الفنى وممثلوها والتى تنص اتفاقية دولية على إعفائها .
7 - توزيعات صناديق الاستثمار فى الأوراق المالية المنشأة وفقًا لقانون سوق رأس المال المشار إليه التى لا يقل استثمارها فى الأوراق المالية وغيرها من أدوات الدين عن (80%) وتوزيعات صناديق الاستثمار القابضة التى يقتصر الاستثمار فيها على صناديق الاستثمار المشار إليها ، وتوزيعات الأرباح التى تحصل عليها هذه الصناديق بعد إضافة (10%) من قيمة هذه التوزيعات إلى الوعاء الخاضع للضريبة مقابل التكاليف غير واجبة الخصم ، وعائدا الاستثمار فى صناديق الاستثمار النقدية ، وعائد السندات المقيدة فى جداول بورصة الأوراق المالية دون سندات الخزانة ، وأرباح صناديق الاستثمار التى يقتصر نشاطها على الاستثمار فى النقد دون غيره .
8 - [ملغى بموجب المادة الرابعة من القانون 53/2014] .
9 - العوائد التى تحصل عليها الأشخاص الاعتبارية عن الأوراق المالية وشهادات الإيداع التى يصدرها البنك المركزى أو الإيرادات الناتجة عن التعامل فيها ، وذلك استثناءً من حكم المادة (56) من هذا القانون .
10 - توزيعات الأرباح التى تحصل عليها الشركة الأم أو الشركة القابضة من الشركات التابعة المقيمة وغير المقيمة بعد إضافة نسبة (10%) من قيمة هذه التوزيعات إلى الوعاء الخاضع للضريبة للشركة الأم أو القابضة مقابل التكاليف غير واجبة الخصم ، وذلك بشرط :
ألا تقل نسبة مساهمة الشركة الأم أو القابضة عن (25%) فى رأس مال الشركة التابعة أو حقوق التصويت .
ألا تقل مدة حيازة الشركة الأم أو القابضة لتلك النسبة عن سنتين أو أن تلتزم بالاحتفاظ بهذه النسبة لمدة سنتين من تاريخ اقتناء الأسهم أو حقوق التصويت .
13 - الأرباح الرأسمالية الناتجة عن التسويات التى تتم على مديونيات شركات قطاع الأعمال العام أو الشركات التى تمتلك الدولة فيها ما لا يقل عن (51%) من رأسمالها وذلك فى إطار تسويات ديون هذه الشركات لدى البنوك وغيرها من الجهات الدائنة ، مقابل نقل ملكية كل أراضيها أو بعضها ، ويكون الإعفاء فى هذه الحالة فى حدود نسبة ما تمتلكه الدولة فى رأسمال هذه الشركات .$b102_6$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 50 AND article_suffix_order = 0;

