    effective_from = '2020-10-01'::date,
    amended_by_law_no = 199,
    amended_by_law_year = 2020,
    change_note = $n102_6$القانون 199/2020 (المادة الثالثة): إضافة بند جديد برقم (13) إلى المادة (50) - إعفاء الأرباح الرأسمالية الناتجة عن تسويات مديونيات شركات قطاع الأعمال العام (أو الشركات التى تملك الدولة فيها 51% فأكثر من رأسمالها) مقابل نقل ملكية أراضٍ، فى حدود نسبة ملكية الدولة. ⚠️ ملاحظة ترقيم: لا يوجد بند (11) أو (12) لهذه المادة فى قاعدة البيانات - تم التأكد (بالرجوع لتقرير الجرد الكامل لسلسلة تعديلات 91/2005، 2026-10-02) أن هذا ليس فجوة بناء، بل القفزة من (10) إلى (13) واردة فى نص المُشرِّع نفسه بالمصدر؛ لا يوجد قانون سابق فى هذه السلسلة أضاف بندًا بهذين الرقمين لهذه المادة. البنود 1-10 والفقرتان الشرطيتان التابعتان للبند (10) بلا تغيير.$n102_6$
WHERE article_id = (
